<script setup lang="ts">
defineProps<{ open:boolean; title:string; message:string; confirmText?:string; loading?:boolean }>();
const emit=defineEmits<{close:[];confirm:[]}>();
</script><template><div v-if="open" class="dialog-backdrop" @click.self="emit('close')"><section class="dialog" role="dialog" aria-modal="true"><h2>{{title}}</h2><p>{{message}}</p><div class="actions"><button type="button" @click="emit('close')" :disabled="loading">Cancel</button><button type="button" class="confirm" :disabled="loading" @click="emit('confirm')">{{loading?'Please wait...':(confirmText||'Confirm')}}</button></div></section></div></template><style scoped>.dialog-backdrop{position:fixed;z-index:100;inset:0;display:grid;place-items:center;padding:18px;background:rgba(15,42,68,.42)}.dialog{width:min(440px,100%);padding:22px;border-radius:8px;background:#fff}.dialog h2{margin:0 0 8px;font-size:1.1rem}.dialog p{margin:0;color:#526579;line-height:1.5}.actions{display:flex;justify-content:flex-end;gap:8px;margin-top:18px}.actions button{height:40px;padding:0 14px;border:1px solid #d6dee7;border-radius:6px;background:#fff;font-weight:750}.actions .confirm{border:0;background:#ff7900;color:#fff}.actions button:disabled{opacity:.55}</style>